namespace Fanex.Age.UI.TotalBets
{

    public partial class Racing_Page : TotalBets_Page
    {

        #region Override

        public override void RenderContent(HtmlTextWriter writer)
        {
            DataTable racingList = View as DataTable;

            Racing_Template tpl = new Racing_Template();

            tpl.Contents.LeagueContents.Clear();
            if (racingList.Rows.Count > 0)
            {
                tpl.Contents.NotFoundContent.Hide();

                // Render league content
                int currentLeagueId = 0;
                int matchIndex = 0;
                decimal winToteTotal = 0, placeToteTotal = 0, winPlaceToteTotal = 0;
                decimal winToteWinLoss = 0, placeToteWinloss = 0, winPlaceToteWinloss = 0;
                decimal winToteFOTotal = 0, placeToteFOTotal = 0, winPlaceFOTotal = 0;
                decimal winToteFOWinloss = 0, placeToteFOWinloss = 0, winPlaceFOWinloss = 0;

                String currentRace = "";
                Racing_Contents_LeagueContents_Block leagueBlock = new Racing_Contents_LeagueContents_Block();
                Racing_Contents_LeagueContents_MatchContents_Block matchBlock = new Racing_Contents_LeagueContents_MatchContents_Block();

                #region Contents
                for (int i = 0; i < racingList.Rows.Count; i++)
                {
                    DataRow dr = racingList.Rows[i];

                    int leagueId = Convert.ToInt32(dr["leagueid"]);

                    if (i == 0 || currentLeagueId != leagueId)
                    {
                        // New league, ignore first row
                        if (i != 0) tpl.Contents.LeagueContents.Append(leagueBlock);

                        matchIndex = 1;
                        currentLeagueId = leagueId;

                        leagueBlock.MatchContents.Clear();
                        leagueBlock.LeagueName = Sunplus.Agent.Model.BL.Cache.CacheRef.GetLeagueName(leagueId);
                        leagueBlock.TotalCols = "9";
                    }
                    else
                    {
                        matchIndex++;
                    }

                    if (matchIndex == 1 || currentRace != dr["race"].ToString())
                    {
                        currentRace = dr["race"].ToString();
                        // Caculate row span for race
                        int j = 0;
                        for (j = i + 1; j < racingList.Rows.Count; j++)
                        {
                            if (currentRace.CompareTo(racingList.Rows[j]["race"]) != 0
                                || currentLeagueId != Convert.ToInt32(racingList.Rows[j]["leagueid"]))
                            {
                                break;
                            }
                        }
                        int raceRowSpan = j - i;
                        matchBlock.RaceTime.Show();
                        matchBlock.RaceTime.RaceRowspan = "rowspan='" + raceRowSpan + "'";
                    }
                    else
                    {
                        matchBlock.RaceTime.Hide();
                    }

                    RenderMatchRow(matchBlock, dr, matchIndex, i + 1);

                    leagueBlock.MatchContents.Append(matchBlock);


                    winToteTotal += Convert.ToDecimal(dr["Total_Win_Tote"]);
                    placeToteTotal += Convert.ToDecimal(dr["Total_Place_Tote"]);
                    winPlaceToteTotal += Convert.ToDecimal(dr["Total_WinPlace_Tote"]);
                    winToteWinLoss += Convert.ToDecimal(dr["Winloss_Win_Tote"]);
                    placeToteWinloss += Convert.ToDecimal(dr["Winloss_Place_Tote"]);
                    winPlaceToteWinloss += Convert.ToDecimal(dr["Winloss_WinPlace_Tote"]);
                    winToteFOTotal += Convert.ToDecimal(dr["Total_Win_FO"]);
                    placeToteFOTotal += Convert.ToDecimal(dr["Total_Place_FO"]);
                    winPlaceFOTotal += Convert.ToDecimal(dr["Total_WinPlace_FO"]);
                    winToteFOWinloss += Convert.ToDecimal(dr["Winloss_Win_FO"]);
                    placeToteFOWinloss += Convert.ToDecimal(dr["Winloss_Place_FO"]);
                    winPlaceFOWinloss += Convert.ToDecimal(dr["Winloss_WinPlace_FO"]);
                }

                if (leagueBlock != null) tpl.Contents.LeagueContents.Append(leagueBlock);
                #endregion

                RenderTotalRow(tpl.Contents.TotalContents, winToteTotal, placeToteTotal, winPlaceToteTotal, winToteWinLoss, placeToteWinloss, winPlaceToteWinloss, placeToteFOTotal, placeToteFOTotal, winPlaceFOTotal, winToteFOWinloss, placeToteFOWinloss, winPlaceFOWinloss);

            }
            else
            {
                tpl.Contents.NotFoundContent.NoFoundColSpan = "9";
                tpl.Contents.TotalContents.Hide();
            }

            if (_fullMode)
            {
                writer.Write(tpl);
            }
            else
            {
                writer.Write(tpl.Contents);
            }
        }

        public override object ValidateRequest(System.Collections.Hashtable p)
        {
            return null;
        }

        public override object InvokeData(System.Collections.Hashtable p)
        {
            return _TotalBetsBO.GetHorseRacing();
        }
        #endregion

        #region Utility

        /// <summary>
        /// Render match row
        /// </summary>
        /// <param name="matchBlock"></param>
        /// <param name="dr"></param>
        /// <param name="matchIndex"></param>
        /// <param name="rowIndex"></param>
        private void RenderMatchRow(Racing_Contents_LeagueContents_MatchContents_Block matchBlock, DataRow dr, int matchIndex, int rowIndex)
        {
            // Render match content
            matchBlock.ColorClass = (matchIndex % 2) == 0 ? Fanex.Age.UI.Common.RowBgEven : Fanex.Age.UI.Common.RowBgOdd;
            matchBlock.ColorOver = Fanex.Age.UI.Common.RowBgOver;
            matchBlock.RaceTime.ColorOver = Fanex.Age.UI.Common.RowBgOver;

            if (String.Compare(dr["oddsstatus"].ToString(), BetListStatus.Running, true) == 0)
            {
                matchBlock.RaceTime.ColorStatus = "Pink";
            }
            else
            {
                matchBlock.RaceTime.ColorStatus = Fanex.Age.UI.Common.RowBgOdd;
            }

            matchBlock.RaceTime.KickOffDay = Formater.ShortDateFormat(dr["kickofftime"]);
            matchBlock.RaceTime.KickOffTime = Convert.ToDateTime(dr["kickofftime"]).ToString("hh:mm:ss tt");
            matchBlock.RaceTime.RaceVal = dr["race"].ToString();
            matchBlock.RaceTime.HRStatusTip = dr["oddsstatus"].ToString();
            matchBlock.No = dr["horseno"].ToString();
            matchBlock.Horse = Sunplus.Agent.Model.BL.Cache.CacheRef.GetHorseTeamName(dr["teamid"]);

            RenderTote(matchBlock, dr);
        }
        /// <summary>
        /// Render Tote
        /// </summary>
        /// <param name="matchBlock"></param>
        /// <param name="dr"></param>
        private void RenderTote(Racing_Contents_LeagueContents_MatchContents_Block matchBlock, DataRow dr)
        {

            #region WinTote
            if (Convert.ToInt32(dr["Total_Win_Tote"]) == 0)
            {
                matchBlock.WinTote.Hide();
                matchBlock.WinToteValue.Show();
                matchBlock.WinToteValue.WinToteTotal = Formater.FormatNumber2(dr["Total_Win_Tote"], CurrentUserSession.Language);
            }
            else
            {
                matchBlock.WinTote.Show();
                matchBlock.WinToteValue.Hide();
                matchBlock.WinTote.WinToteTotal = RedForNegativeAmount(dr["Total_Win_Tote"], 0);
                matchBlock.WinTote.MatchId = dr["matchid"].ToString();
                matchBlock.WinTote.BetType = Fanex.Age.UI.Common.BetListByBetTypeMatch;

            }
            matchBlock.WinToteWinloss = RedForNegativeAmount(dr["Winloss_Win_Tote"], 2);
            #endregion

            #region PlaceTote
            if (Convert.ToInt32(dr["Total_Place_Tote"]) == 0)
            {
                matchBlock.PlaceTote.Hide();
                matchBlock.PlaceToteValue.Show();
                matchBlock.PlaceToteValue.PlaceToteTotal = Formater.FormatNumber2(dr["Total_Place_Tote"], CurrentUserSession.Language);
            }
            else
            {
                matchBlock.PlaceTote.Show();
                matchBlock.PlaceToteValue.Hide();
                matchBlock.PlaceTote.PlaceToteTotal = RedForNegativeAmount(dr["Total_Place_Tote"], 0);
                matchBlock.PlaceTote.MatchId = dr["matchid"].ToString();
                matchBlock.PlaceTote.BetType = Fanex.Age.UI.Common.BetListByBetTypeMatch;

            }
            matchBlock.PlaceToteWinloss = RedForNegativeAmount(dr["Winloss_Place_Tote"], 2);
            #endregion

            #region WinPlaceTote
            if (Convert.ToInt32(dr["Total_WinPlace_Tote"]) == 0)
            {
                matchBlock.WinplaceTote.Hide();
                matchBlock.WinplaceToteValue.Show();
                matchBlock.WinplaceToteValue.WinplaceToteTotal = Formater.FormatNumber2(dr["Total_WinPlace_Tote"], CurrentUserSession.Language);
            }
            else
            {
                matchBlock.WinplaceTote.Show();
                matchBlock.WinplaceToteValue.Hide();
                matchBlock.WinplaceTote.WinplaceToteTotal = RedForNegativeAmount(dr["Total_WinPlace_Tote"], 0);
                matchBlock.WinplaceTote.MatchId = dr["matchid"].ToString();
                matchBlock.WinplaceTote.BetType = Fanex.Age.UI.Common.BetListByBetTypeMatch;

            }
            matchBlock.WinplaceToteWinloss = RedForNegativeAmount(dr["Winloss_WinPlace_Tote"], 2);
            #endregion

        }

        /// <summary>
        /// Round color for negative number
        /// </summary>
        /// <param name="number"></param>
        /// <returns></returns>
        public static string RedForNegativeAmount(object amount, byte decDigits)
        {

            if ((decimal)amount < 0)
                return "<font color='#eb6003'>" + Formater.DecFormat(amount, decDigits) + "</font>";
            else
                return Formater.DecFormat(amount, decDigits);

        }
        /// <summary>
        /// Render Total row
        /// </summary>
        /// <param name="totalBlock"></param>
        /// <param name="winToteTotal"></param>
        /// <param name="placeToteTotal"></param>
        /// <param name="winPlaceToteTotal"></param>
        /// <param name="winToteWinLoss"></param>
        /// <param name="placeToteWinloss"></param>
        /// <param name="winPlaceToteWinloss"></param>
        /// <param name="winToteFOTotal"></param>
        /// <param name="placeToteFOTotal"></param>
        /// <param name="winPlaceFOTotal"></param>
        /// <param name="winToteFOWinloss"></param>
        /// <param name="placeToteFOWinloss"></param>
        /// <param name="winPlaceFOWinloss"></param>
        private void RenderTotalRow(Racing_Contents_TotalContents_Block totalBlock,
            decimal winToteTotal, decimal placeToteTotal, decimal winPlaceToteTotal,
            decimal winToteWinLoss, decimal placeToteWinloss, decimal winPlaceToteWinloss,
            decimal winToteFOTotal, decimal placeToteFOTotal, decimal winPlaceFOTotal,
            decimal winToteFOWinloss, decimal placeToteFOWinloss, decimal winPlaceFOWinloss)
        {
            totalBlock.SumWinTotal = Formater.DecFormat(winToteTotal, 0);
            totalBlock.SumWinWinloss = Formater.DecFormat(winToteWinLoss, 2);
            totalBlock.SumPlaceTotal = Formater.DecFormat(placeToteTotal, 0);
            totalBlock.SumPlaceWinloss = Formater.DecFormat(placeToteWinloss, 2);
            totalBlock.SumWinplaceTotal = Formater.DecFormat(winPlaceToteTotal, 0);
            totalBlock.SumWinplaceWinloss = Formater.DecFormat(winPlaceToteWinloss, 2);
        }

        #endregion
    }

}
